<script setup lang="ts">
import { computed, watch } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AppLayout from '@/layouts/AppLayout.vue';
import type { BreadcrumbItem } from '@/types';
type Vehicle={id:number;name:string;brand:string;model:string;type:string;seats:number;description:string|null;image:string|null;price:number;status:string};
const props=defineProps<{vehicles:Vehicle[];initial:{pickup_location:string;destination:string;travel_date:string;pickup_time:string;passengers:number}}>();
const minDate=new Date().toLocaleDateString('en-CA');
const form=useForm({customer_name:'',phone:'',email:'',pickup_location:props.initial.pickup_location,destination:props.initial.destination,travel_date:props.initial.travel_date,pickup_time:props.initial.pickup_time,passengers:Math.max(1,props.initial.passengers||1),vehicle_id:props.vehicles[0]?.id??null,notes:''});
const selectedVehicle=computed(()=>props.vehicles.find(v=>v?.id===form.vehicle_id)??null);
const passengerLimit=computed(()=>selectedVehicle.value?.seats??60);
watch(passengerLimit,limit=>{if(form.passengers>limit)form.passengers=limit},{immediate:true});
const breadcrumbs:BreadcrumbItem[]=[{title:'Đặt xe',href:'/dat-xe'}];
const submit=()=>form.post('/dat-xe');
</script>
<template><AppLayout :breadcrumbs="breadcrumbs"><Head title="Đặt xe"/><div class="min-w-0 p-3 sm:p-6 lg:p-8"><div class="mx-auto grid max-w-6xl gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(280px,360px)]"><div class="min-w-0 rounded-xl border bg-card p-4 sm:p-6"><div class="mb-6"><Link href="/" class="text-sm text-muted-foreground hover:text-foreground">← Trang chủ</Link><h1 class="mt-2 text-2xl font-bold sm:text-3xl">Đặt xe</h1><p class="mt-1 text-sm text-muted-foreground">Gửi yêu cầu đặt xe, chúng tôi sẽ liên hệ để xác nhận.</p></div><form class="grid gap-4" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><label class="grid gap-1 text-sm">Họ và tên<input v-model="form.customer_name" required maxlength="120" class="min-w-0 rounded-md border px-3 py-2"/><span v-if="form.errors.customer_name" class="text-xs text-destructive">{{form.errors.customer_name}}</span></label><label class="grid gap-1 text-sm">Số điện thoại<input v-model="form.phone" required inputmode="tel" class="min-w-0 rounded-md border px-3 py-2"/><span v-if="form.errors.phone" class="text-xs text-destructive">{{form.errors.phone}}</span></label></div><label class="grid gap-1 text-sm">Email<input v-model="form.email" required type="email" class="min-w-0 rounded-md border px-3 py-2"/><span v-if="form.errors.email" class="text-xs text-destructive">{{form.errors.email}}</span></label><div class="grid gap-4 sm:grid-cols-2"><label class="grid gap-1 text-sm">Điểm đón<input v-model="form.pickup_location" required maxlength="255" class="min-w-0 rounded-md border px-3 py-2"/><span v-if="form.errors.pickup_location" class="text-xs text-destructive">{{form.errors.pickup_location}}</span></label><label class="grid gap-1 text-sm">Điểm đến<input v-model="form.destination" required maxlength="255" class="min-w-0 rounded-md border px-3 py-2"/><span v-if="form.errors.destination" class="text-xs text-destructive">{{form.errors.destination}}</span></label></div><div class="grid gap-4 sm:grid-cols-2"><label class="grid gap-1 text-sm">Ngày đi<input v-model="form.travel_date" :min="minDate" required type="date" class="min-w-0 rounded-md border px-3 py-2"/><span v-if="form.errors.travel_date" class="text-xs text-destructive">{{form.errors.travel_date}}</span></label><label class="grid gap-1 text-sm">Giờ đón<input v-model="form.pickup_time" required type="time" class="min-w-0 rounded-md border px-3 py-2"/><span v-if="form.errors.pickup_time" class="text-xs text-destructive">{{form.errors.pickup_time}}</span></label></div><label class="grid gap-1 text-sm">Số hành khách<input v-model.number="form.passengers" :min="1" :max="passengerLimit" required type="number" class="min-w-0 rounded-md border px-3 py-2"/><span v-if="form.errors.passengers" class="text-xs text-destructive">{{form.errors.passengers}}</span></label><div class="grid gap-3"><div class="text-sm font-medium">Chọn xe</div><label class="flex min-w-0 cursor-pointer gap-3 rounded-lg border p-3 has-[:checked]:border-primary"><input v-model="form.vehicle_id" :value="null" type="radio" class="mt-1 shrink-0"/><div class="min-w-0"><div class="font-medium">Để chúng tôi tư vấn xe</div><div class="text-xs text-muted-foreground">Chưa cần chọn xe, chúng tôi sẽ chọn xe phù hợp theo số hành khách.</div></div></label><div v-if="!props.vehicles.length" class="rounded-lg border p-4 text-sm text-muted-foreground">Hiện chưa có xe khả dụng. Bạn vẫn có thể gửi yêu cầu để được tư vấn.</div><label v-for="vehicle in props.vehicles" :key="vehicle.id" class="flex min-w-0 cursor-pointer gap-3 rounded-lg border p-3 has-[:checked]:border-primary"><input v-model="form.vehicle_id" :value="vehicle.id" type="radio" class="mt-1 shrink-0"/><div class="min-w-0"><div class="truncate font-medium">{{vehicle.name}}</div><div class="text-xs text-muted-foreground">{{vehicle.brand}} {{vehicle.model}} · {{vehicle.seats}} chỗ</div><p v-if="vehicle.description" class="mt-1 line-clamp-2 text-sm text-muted-foreground">{{vehicle.description}}</p></div></label></div><label class="grid gap-1 text-sm">Ghi chú<textarea v-model="form.notes" maxlength="2000" class="min-h-24 min-w-0 rounded-md border px-3 py-2"/></label><div class="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Link href="/" class="rounded-md border px-4 py-2 text-center">Hủy</Link><button :disabled="form.processing" type="submit" class="rounded-md bg-primary px-4 py-2 font-medium text-primary-foreground disabled:opacity-50">{{form.processing?'Đang gửi...':'Gửi yêu cầu đặt xe'}}</button></div></form></div><aside class="min-w-0 lg:sticky lg:top-6 lg:self-start"><div class="rounded-xl border bg-muted/30 p-4 sm:p-5"><h2 class="font-semibold">Thông tin xe</h2><div v-if="selectedVehicle" class="mt-3"><div class="text-lg font-semibold">{{selectedVehicle.name}}</div><div class="text-sm text-muted-foreground">{{selectedVehicle.brand}} {{selectedVehicle.model}}</div><div class="mt-3 text-sm">{{selectedVehicle.seats}} chỗ · {{selectedVehicle.type}}</div><div v-if="selectedVehicle.price" class="mt-2 font-medium">{{Number(selectedVehicle.price).toLocaleString('vi-VN')}} đ</div></div><div v-else class="mt-3 text-sm text-muted-foreground">Chúng tôi sẽ tư vấn xe phù hợp.</div></div></aside></div></div></AppLayout></template>
